def is_2_digit_good(d2, d1):
    # m = 10*d2 + d1. Digits must be distinct and non-zero.
    if d2 == d1 or d2 == 0 or d1 == 0:
        return False

    # Check d1 | 10*d2 (Removing d2)
    cond1 = (10 * d2) % d1 == 0

    # Check d2 | d1 (Removing d1)
    cond2 = d1 % d2 == 0

    return cond1 or cond2

good_numbers = []
for d2 in range(9, 0, -1):
    for d1 in range(9, 0, -1):
        if d1 != d2:
            if is_2_digit_good(d2, d1):
                m = 10 * d2 + d1
                good_numbers.append(m)

good_numbers.sort(reverse=True)
print("2-digit good numbers (largest first):", good_numbers)

